import {LESSON,SIGNS} from './course.js?v=20260928-4';
export function resultsMarkup(summary,best,persisted){return `<div class="results-top"><div><div class="eyebrow">УРОК ЗАВЕРШЁН</div><h2>У тебя получилось.</h2><p>Ты показал три жеста и собрал фразу<br>«Да. Я тебя люблю!»</p></div><div class="result-badge" aria-hidden="true">✓</div></div><div class="stats"><div class="stat"><strong>${summary.score}<small>/100</small></strong><span>Учебные баллы</span></div><div class="stat"><strong>3/3</strong><span>Жестов освоено</span></div><div class="stat"><strong>${Math.floor(summary.seconds/60)}:${String(summary.seconds%60).padStart(2,'0')}</strong><span>Время урока</span></div><div class="stat"><strong>${summary.accuracy}<small>%</small></strong><span>Среднее соответствие</span></div><div class="stat"><strong>${summary.hints}</strong><span>Подсказок получено</span></div><div class="stat"><strong class="best-gesture">${SIGNS[summary.bestGesture]?.name??"—"}</strong><span>Лучший жест</span></div></div><table><thead><tr><th>Жест</th><th>Подсказки</th><th>Что повторить</th></tr></thead><tbody>${LESSON.map(s=>`<tr><td>${SIGNS[s].name} ✓</td><td>${summary.errors[s]}</td><td>${summary.errors[s]?s==='ily'?'Форму пальцев':s==='yes'?'Кивок кистью':'Смыкание пальцев':'Всё получилось'}</td></tr>`).join('')}</tbody></table><p class="muted">Соответствие — средняя доля соблюдённых правил во время практики, не оценка владения языком. Баллы = 100 − 3 за каждую устойчивую подсказку (не ниже 50 после завершения). Это результат упражнения, не оценка владения ASL. ${persisted?'Лучший результат в этом браузере: '+best.score+'/100.':'Браузер не разрешил сохранить результат.'}</p><div class="result-actions"><button class="button primary" id="restart-button" data-gesture>Повторить урок ↻</button><button class="button secondary" id="stop-button" data-gesture>Выключить камеру</button></div>`;}
